196	/**
197	 * @brief 简单封装，拷贝vector data中数据以创建tensor
198	 * @details 用于创建outTensorType类型的tensor
199	 * @param contextPtr context指针
200	 * @param stream stream
201	 * @param data 输入vector数据
202	 * @param outTensorType 期望输出tensor数据类型
203	 * @param format 输出tensor的格式，即NZ，ND等
204	 * @param shape 输出tensor的shape
205	 * @param outTensor 返回创建的tensor
206	 */
207	template <typename T>
208	atb::Status CreateTensorFromVector(atb::Context *contextPtr, aclrtStream stream, std::vector<T> data,
209	                                   const aclDataType outTensorType, const aclFormat format, std::vector<int64_t> shape,
210	                                   atb::Tensor &outTensor, const aclDataType inTensorType = ACL_DT_UNDEFINED)
211	{
212	    atb::Tensor tensor;
213	    aclDataType intermediateType;
214	    switch (outTensorType) {
215	        case aclDataType::ACL_FLOAT16:
216	        case aclDataType::ACL_BF16:
217	        case aclDataType::ACL_DOUBLE:
218	            intermediateType = aclDataType::ACL_FLOAT;
219	            break;
220	        default:
221	            intermediateType = outTensorType;
222	    }
223	    if (inTensorType == outTensorType && inTensorType != ACL_DT_UNDEFINED) {
224	        intermediateType = outTensorType;
225	    }
226	    aclFormat tensorFormat = format;
227	    if (intermediateType != outTensorType && format == aclFormat::ACL_FORMAT_FRACTAL_NZ) {
228	        tensorFormat = aclFormat::ACL_FORMAT_ND;
229	    }
230	    CHECK_STATUS(CreateTensor(intermediateType, tensorFormat, shape, tensor));
231	    CHECK_STATUS(aclrtMemcpy(tensor.deviceData, tensor.dataSize, data.data(), sizeof(T) * data.size(),
232	                             ACL_MEMCPY_HOST_TO_DEVICE));
233	    CHECK_STATUS(CreateTensor(outTensorType, aclFormat::ACL_FORMAT_ND, shape, outTensor));
234	    if (intermediateType == outTensorType) {
235	        // 原始创建的tensor类型，不需要转换
236	        outTensor = tensor;
237	        return atb::ErrorType::NO_ERROR;
238	    }
239	    CHECK_STATUS(CastOp(contextPtr, stream, tensor, outTensorType, outTensor));
240	    // 直接赋值将tensor转成需要的数据格式，或者使用提供的TransdataOp函数进行数据格式转换，详细用法见同级目录README.md
241	    outTensor.desc.format = format;
242	    return atb::ErrorType::NO_ERROR;
243	}
244	
245	#endif
